import { useScrollWindow } from '../../src/ui/use_scroll_window';

describe('useScrollWindow', () => {
  const makeItems = (n: number) => Array.from({ length: n }, (_, i) => `item${i}`);

  it('returns full list if items.length <= visibleRows', () => {
    const items = makeItems(5);
    const { visible, offset } = useScrollWindow(items, 2, 8);
    expect(visible).toEqual(items);
    expect(offset).toBe(0);
  });

  it('centers window on cursor when possible', () => {
    const items = makeItems(20);
    const { visible, offset } = useScrollWindow(items, 10, 8);
    expect(offset).toBe(6); // 10 - 4
    expect(visible).toEqual(items.slice(6, 14));
  });

  it('clamps offset to 0 when cursor is near start', () => {
    const items = makeItems(20);
    const { visible, offset } = useScrollWindow(items, 1, 8);
    expect(offset).toBe(0);
    expect(visible).toEqual(items.slice(0, 8));
  });

  it('clamps offset to maxOffset when cursor is near end', () => {
    const items = makeItems(20);
    const { visible, offset } = useScrollWindow(items, 19, 8);
    expect(offset).toBe(12); // 20 - 8
    expect(visible).toEqual(items.slice(12, 20));
  });

  it('handles empty items array', () => {
    const { visible, offset } = useScrollWindow([], 0, 8);
    expect(visible).toEqual([]);
    expect(offset).toBe(0);
  });

  it('handles cursor < 0 (negative index)', () => {
    const items = makeItems(10);
    const { visible, offset } = useScrollWindow(items, -3, 5);
    expect(offset).toBe(0);
    expect(visible).toEqual(items.slice(0, 5));
  });

  it('handles cursor > items.length (overflow index)', () => {
    const items = makeItems(10);
    const { visible, offset } = useScrollWindow(items, 20, 5);
    expect(offset).toBe(5); // 10 - 5
    expect(visible).toEqual(items.slice(5, 10));
  });

  it('handles visibleRows = 1 (single row window)', () => {
    const items = makeItems(10);
    const { visible, offset } = useScrollWindow(items, 5, 1);
    expect(offset).toBe(5);
    expect(visible).toEqual([items[5]]);
  });

  it('handles visibleRows = 0 (no rows visible)', () => {
    const items = makeItems(10);
    const { visible, offset } = useScrollWindow(items, 5, 0);
    expect(offset).toBe(0);
    expect(visible).toEqual([]);
  });

  it('handles visibleRows > items.length', () => {
    const items = makeItems(3);
    const { visible, offset } = useScrollWindow(items, 1, 10);
    expect(offset).toBe(0);
    expect(visible).toEqual(items);
  });

  it('returns correct window for odd visibleRows', () => {
    const items = makeItems(10);
    const { visible, offset } = useScrollWindow(items, 5, 5);
    expect(offset).toBe(3); // 5 - 2
    expect(visible).toEqual(items.slice(3, 8));
  });

  it('returns correct window for even visibleRows', () => {
    const items = makeItems(10);
    const { visible, offset } = useScrollWindow(items, 5, 4);
    expect(offset).toBe(3); // 5 - 2
    expect(visible).toEqual(items.slice(3, 7));
  });

  it('handles visibleRows undefined (defaults to 8)', () => {
    const items = makeItems(20);
    const { visible, offset } = useScrollWindow(items, 10);
    expect(offset).toBe(6);
    expect(visible).toEqual(items.slice(6, 14));
  });

  it('does not mutate input array', () => {
    const items = makeItems(10);
    const itemsCopy = [...items];
    useScrollWindow(items, 5, 4);
    expect(items).toEqual(itemsCopy);
  });
});
